local GrainHopperLinerMaker = {}
local PRODUCTS = {
    iron_grainhopperliner = { name = "Železni obloga za lijake", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni obloga za lijake za mlinarje." },
    bronze_grainhopperliner = { name = "Bronast obloga za lijake", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast obloga za lijake za mlinarje." },
    silver_grainhopperliner = { name = "Srebrn obloga za lijake", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn obloga za lijake za mlinarje." },
    gilded_grainhopperliner = { name = "Pozlačen obloga za lijake", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen obloga za lijake za mlinarje." },
    jewel_set_grainhopperliner = { name = "Draguljast obloga za lijake", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast obloga za lijake za mlinarje." },
    royal_sovereign_grainhopperliner = { name = "Kraljevski suveren obloga za lijake", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren obloga za lijake z biseri za krono." },
}
local BUILDINGS = {
    grainhopperliner_workshop = { name = "Grainhopperliner delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    grainhopperliner_house = { name = "Grainhopperliner hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_grainhopperliner_atelier = { name = "Mojstrski grainhopperliner atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_grainhopperliner_palace = { name = "Suverena grainhopperliner palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GrainHopperLinerMaker.ironStock=12; GrainHopperLinerMaker.bronzeStock=10; GrainHopperLinerMaker.woodStock=14; GrainHopperLinerMaker.leatherStock=12; GrainHopperLinerMaker.silverStock=8; GrainHopperLinerMaker.goldStock=6; GrainHopperLinerMaker.jewelStock=4; GrainHopperLinerMaker.pearlStock=4
GrainHopperLinerMaker.productStock = {}; GrainHopperLinerMaker.buildings = {}; GrainHopperLinerMaker.maker = nil; GrainHopperLinerMaker.activeMaking = {}; GrainHopperLinerMaker.totalProducts = 0; GrainHopperLinerMaker.dayTimer = 0
function GrainHopperLinerMaker.init() GrainHopperLinerMaker.ironStock=12; GrainHopperLinerMaker.bronzeStock=10; GrainHopperLinerMaker.woodStock=14; GrainHopperLinerMaker.leatherStock=12; GrainHopperLinerMaker.silverStock=8; GrainHopperLinerMaker.goldStock=6; GrainHopperLinerMaker.jewelStock=4; GrainHopperLinerMaker.pearlStock=4; GrainHopperLinerMaker.productStock={}; GrainHopperLinerMaker.buildings={}; GrainHopperLinerMaker.maker=nil; GrainHopperLinerMaker.activeMaking={}; GrainHopperLinerMaker.totalProducts=0; GrainHopperLinerMaker.dayTimer=0; print("[GrainHopperLinerMaker] Royal Grain Hopper Liner Maker System initialized (6 products, 4 buildings)") end
function GrainHopperLinerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainHopperLinerMaker.maker={name=n or ("Oblogar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oblogar najet: %s (spretnost: %d)",GrainHopperLinerMaker.maker.name,s),"success") end; return true end
function GrainHopperLinerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainHopperLinerMaker.build(id) local ok,e=GrainHopperLinerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainHopperLinerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainHopperLinerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainHopperLinerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainHopperLinerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainHopperLinerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainHopperLinerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainHopperLinerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainHopperLinerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainHopperLinerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainHopperLinerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainHopperLinerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainHopperLinerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainHopperLinerMaker.buildings==0 then return false,"Potrebna obložna delavnica" end; if not GrainHopperLinerMaker.maker then return false,"Potreben oblogar" end; return true end
function GrainHopperLinerMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainHopperLinerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainHopperLinerMaker.ironStock=GrainHopperLinerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainHopperLinerMaker.bronzeStock=GrainHopperLinerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainHopperLinerMaker.woodStock=GrainHopperLinerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainHopperLinerMaker.leatherStock=GrainHopperLinerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainHopperLinerMaker.silverStock=GrainHopperLinerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainHopperLinerMaker.goldStock=GrainHopperLinerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainHopperLinerMaker.jewelStock=GrainHopperLinerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainHopperLinerMaker.pearlStock=GrainHopperLinerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainHopperLinerMaker.maker then t=math.max(1,t-math.floor(GrainHopperLinerMaker.maker.skill/13)) end; table.insert(GrainHopperLinerMaker.activeMaking,{id="grainhopperliner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainHopperLinerMaker.completeMaking(m) local q=1.0+(GrainHopperLinerMaker.getQualityBonus()/100); if GrainHopperLinerMaker.maker then q=q+(GrainHopperLinerMaker.maker.skill/140) end; q=math.min(2.5,q); GrainHopperLinerMaker.productStock[m.productType]=(GrainHopperLinerMaker.productStock[m.productType] or 0)+m.quantity; GrainHopperLinerMaker.totalProducts=GrainHopperLinerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainHopperLinerMaker.maker then GrainHopperLinerMaker.maker.itemsMade=GrainHopperLinerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainHopperLinerMaker.maker.skill=math.min(100,GrainHopperLinerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obloga izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainhopperliner.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainHopperLinerMaker.update(dt) if not _G.state then return end; GrainHopperLinerMaker.dayTimer=GrainHopperLinerMaker.dayTimer+dt; if GrainHopperLinerMaker.dayTimer>=30 then GrainHopperLinerMaker.dayTimer=0; for i=#GrainHopperLinerMaker.activeMaking,1,-1 do local m=GrainHopperLinerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainHopperLinerMaker.completeMaking(m); table.remove(GrainHopperLinerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainHopperLinerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainHopperLinerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainHopperLinerMaker.getStats() return {ironStock=GrainHopperLinerMaker.ironStock,bronzeStock=GrainHopperLinerMaker.bronzeStock,woodStock=GrainHopperLinerMaker.woodStock,leatherStock=GrainHopperLinerMaker.leatherStock,silverStock=GrainHopperLinerMaker.silverStock,goldStock=GrainHopperLinerMaker.goldStock,jewelStock=GrainHopperLinerMaker.jewelStock,pearlStock=GrainHopperLinerMaker.pearlStock,productStock=GrainHopperLinerMaker.productStock,numBuildings=#GrainHopperLinerMaker.buildings,hasMaker=GrainHopperLinerMaker.maker~=nil,makerName=GrainHopperLinerMaker.maker and GrainHopperLinerMaker.maker.name or "—",makerSkill=GrainHopperLinerMaker.maker and GrainHopperLinerMaker.maker.skill or 0,activeMaking=#GrainHopperLinerMaker.activeMaking,totalProducts=GrainHopperLinerMaker.totalProducts} end
return GrainHopperLinerMaker
